// src/app/localization/LocalizationCatalog.ts
async function parseLocalizationCatalogFromItem(item) {
  const file = item && await item.loadFileContent();
  const json = file && StorageUtilities.getJsonObject(file);
  const [langs, errors] = validateJsonAndAssert(json, {
    type: "array",
    items: {
      type: "string"
    }
  });
  if (errors) {
    return [null, errors];
  }
  return [{ langs }, null];
}

